SELECT p.gender, p.age, i.stay_id, i.intime, i.outtime, i.los, p.dod, s.score, s.p25, s.p75, s.p95, s.tachycardia, s.hypotension, m.mortality_rate FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN stay_scores s ON i.stay_id = s.stay_id JOIN mortality_rates m ON p.dod IS NOT NULL AND m.death_date BETWEEN i.intime AND i.outtime WHERE p.gender = 'M' AND p.age BETWEEN 55 AND 65 AND s.hf_nc_in_24_hours = 1;